-- Baseline schema for Postgres mode, converted from the original MySQL schema-export (generated
-- from the JPA entity mappings via Hibernate's MySQLDialect schema-export tooling -- see
-- JpaEntityMappingTest / SchemaScriptGenerator for how that baseline was produced). MySQL-only
-- syntax was translated for Postgres: `engine=InnoDB` dropped, inline `enum(...)` columns ->
-- varchar(255) (every enum field maps via @Enumerated(EnumType.STRING), so this matches what
-- Hibernate would generate directly under PostgreSQLDialect), `bit` -> boolean, `datetime(6)` ->
-- timestamp(6) (no timezone -- matches the original DATETIME's offset-naive semantics). Hibernate
-- runs with ddl-auto=validate against this schema; it never generates DDL.

create table api_client_allowed_ips (api_client_id varchar(255) not null, ip_address varchar(255));
create table api_client_grant_types (api_client_id varchar(255) not null, grant_type varchar(255));
create table api_client_redirect_uris (api_client_id varchar(255) not null, redirect_uri varchar(255));
create table api_client_role_ids (api_client_id varchar(255) not null, role_id varchar(255));
create table api_client_scopes (api_client_id varchar(255) not null, scope varchar(255));
create table api_clients (id varchar(255) not null, access_token_validity_seconds integer, active boolean, application_id varchar(255), created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), version bigint, authentication_method varchar(255), client_id varchar(255), client_secret_hash varchar(255), client_type varchar(255), description varchar(255), name varchar(255), refresh_token_validity_seconds integer, tenant_id varchar(255), primary key (id));
create table applications (id varchar(255) not null, active boolean, app_version varchar(255), attributes TEXT, created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), version bigint, authentication_mode varchar(255), base_url varchar(255), code varchar(255), description varchar(255), display_order integer, icon_file_type varchar(255), icon_location varchar(255), icon_model_key varchar(255), icon_name varchar(255), icon_prefix_folder varchar(255), icon_retention_policy varchar(255), icon_size bigint, icon_title varchar(255), icon_version_id varchar(255), landing_page varchar(255), mfa_required boolean, name varchar(255), owner_team varchar(255), sso_enabled boolean, support_email varchar(255), system_application boolean, type varchar(255), primary key (id));
create table audit_logs (id varchar(255) not null, action varchar(255), application_id varchar(255), browser varchar(255), changes TEXT, correlation_id varchar(255), created_at timestamp(6), device varchar(255), entity_id varchar(255), entity_type varchar(255), execution_time_ms bigint, ip_address varchar(255), new_value TEXT, old_value TEXT, operating_system varchar(255), remarks varchar(255), request_id varchar(255), status varchar(255), tenant_id varchar(255), user_agent varchar(255), user_id varchar(255), username varchar(255), primary key (id));
create table group_roles (group_id varchar(255) not null, role_code varchar(255), idx integer not null, primary key (group_id, idx));
create table group_users (group_id varchar(255) not null, user_id varchar(255), idx integer not null, primary key (group_id, idx));
create table groups (id varchar(255) not null, active boolean, attributes TEXT, created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), version bigint, business_unit varchar(255), code varchar(255), cost_center varchar(255), department varchar(255), description varchar(255), dynamic boolean, effective_from timestamp(6), effective_until timestamp(6), max_users integer, name varchar(255), system_group boolean, tenant_id varchar(255), type varchar(255), primary key (id));
create table notification_template_variables (template_id varchar(255) not null, variable varchar(255), idx integer not null, primary key (template_id, idx));
create table notification_templates (id varchar(255) not null, active boolean, application_id varchar(255), created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), audit_version bigint, body TEXT, channel varchar(255), code varchar(255), description varchar(255), engine varchar(255), language varchar(255), name varchar(255), subject varchar(255), system_template boolean, tenant_id varchar(255), version integer, primary key (id));
create table password_history (id varchar(255) not null, algorithm varchar(255), created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), version bigint, change_reason varchar(255), changed_by varchar(255), credential_id varchar(255), password_expiry_at timestamp(6), password_hash varchar(255), password_version integer, user_id varchar(255), primary key (id));
create table permissions (id varchar(255) not null, action varchar(255), active boolean, application_code varchar(255), attributes TEXT, created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), version bigint, code varchar(255), description varchar(255), display_name varchar(255), module varchar(255), resource varchar(255), system_permission boolean, primary key (id));
create table refresh_tokens (id varchar(255) not null, created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), version bigint, client_id varchar(255), device_id varchar(255), expires_at timestamp(6), ip_address varchar(255), issued_at timestamp(6), jwt_id varchar(255), last_used_at timestamp(6), principal_id varchar(255), principal_type varchar(255), revoked boolean, revoked_reason varchar(255), rotation_count integer, session_id varchar(255), token_hash varchar(255), token_id varchar(255), user_agent varchar(255), primary key (id));
create table security_policies (id varchar(255) not null, account_policy TEXT, active boolean, api_security_policy TEXT, application_id varchar(255), created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), version bigint, description varchar(255), effective_from timestamp(6), effective_until timestamp(6), login_policy TEXT, mfa_policy TEXT, name varchar(255), password_policy TEXT, session_policy TEXT, system_policy boolean, tenant_id varchar(255), primary key (id));
create table tenants (id varchar(255) not null, active boolean, created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), version bigint, code varchar(255), country varchar(255), currency varchar(255), default_language varchar(255), description varchar(255), email_domain varchar(255), legal_name varchar(255), logo_file_type varchar(255), logo_location varchar(255), logo_model_key varchar(255), logo_name varchar(255), logo_prefix_folder varchar(255), logo_retention_policy varchar(255), logo_size bigint, logo_title varchar(255), logo_version_id varchar(255), max_applications integer, max_users integer, name varchar(255), settings TEXT, status varchar(255), support_email varchar(255), support_phone varchar(255), system_tenant boolean, time_zone varchar(255), type varchar(255), website varchar(255), primary key (id));
create table uam_role_permissions (role_id varchar(255) not null, permission_code varchar(255), idx integer not null, primary key (role_id, idx));
create table uam_roles (id varchar(255) not null, active boolean, assigned_by varchar(255), assignment_reason varchar(255), assignment_type varchar(255), attributes TEXT, created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), version bigint, code varchar(255), default_role boolean, description varchar(255), editable boolean, effective_from timestamp(6), effective_until timestamp(6), name varchar(255), system_role boolean, tenant_id varchar(255), primary key (id));
create table uam_user_roles (user_id varchar(255) not null, role_code varchar(255), idx integer not null, primary key (user_id, idx));
create table uam_users (id varchar(255) not null, active boolean, api_user boolean, attributes TEXT, created_at timestamp(6), created_by varchar(255), deleted boolean, deleted_at timestamp(6), deleted_by varchar(255), updated_at timestamp(6), updated_by varchar(255), version bigint, department_id varchar(255), designation_id varchar(255), display_name varchar(255), email varchar(255), employee_code varchar(255), first_name varchar(255), last_name varchar(255), middle_name varchar(255), gender varchar(255), joining_date date, location_id varchar(255), country_code varchar(255), number varchar(255), preferred_language varchar(255), file_type varchar(255), location varchar(255), model_key varchar(255), name varchar(255), prefix_folder varchar(255), retention_policy varchar(255), size bigint, title varchar(255), version_id varchar(255), relieving_date date, reporting_manager_id varchar(255), status varchar(255), tenant_id varchar(255), timezone varchar(255), user_name varchar(255), primary key (id));
create table user_credentials (id varchar(255) not null, access_token varchar(255), active boolean, created_at timestamp(6), created_by varchar(255), email_verified boolean, force_password_change boolean, last_authenticated_at timestamp(6), last_sync_at timestamp(6), metadata TEXT, password_changed_at timestamp(6), password_expiry_at timestamp(6), password_hash varchar(255), password_salt varchar(255), phone_verified boolean, primary_credential boolean, provider varchar(255), provider_user_id varchar(255), refresh_token varchar(255), temporary_password_expiry timestamp(6), temporary_password_hash varchar(255), token_expiry timestamp(6), updated_at timestamp(6), updated_by varchar(255), user_id varchar(255), verified boolean, version bigint, primary key (id));
create table user_devices (id varchar(255) not null, active boolean, block_reason varchar(255), blocked boolean, browser varchar(255), browser_version varchar(255), city varchar(255), country varchar(255), created_at timestamp(6), created_by varchar(255), device_fingerprint varchar(255), device_name varchar(255), device_type varchar(255), device_uuid varchar(255), last_active_at timestamp(6), last_ip_address varchar(255), last_login_at timestamp(6), last_logout_at timestamp(6), manufacturer varchar(255), metadata TEXT, model varchar(255), operating_system varchar(255), operating_system_version varchar(255), platform varchar(255), push_notification_token varchar(255), registered_at timestamp(6), state varchar(255), trusted boolean, updated_at timestamp(6), updated_by varchar(255), user_id varchar(255), verified boolean, version bigint, primary key (id));
create table user_login_security (id varchar(255) not null, account_locked boolean, active boolean, captcha_required boolean, created_at timestamp(6), created_by varchar(255), failed_login_attempts integer, failed_login_count bigint, first_login boolean, force_password_change boolean, last_device_id varchar(255), last_failed_login_at timestamp(6), last_failed_login_ip varchar(255), last_login_ip varchar(255), last_login_location varchar(255), last_password_reset_request_at timestamp(6), last_successful_login_at timestamp(6), lock_reason varchar(255), locked_at timestamp(6), mfa_required boolean, otp_verification_required boolean, password_expiry_at timestamp(6), previous_successful_login_at timestamp(6), risk_score integer, successful_login_count bigint, suspicious_activity boolean, unlock_at timestamp(6), updated_at timestamp(6), updated_by varchar(255), user_id varchar(255), version bigint, primary key (id));
create table user_mfa (id varchar(255) not null, active boolean, created_at timestamp(6), created_by varchar(255), device_id varchar(255), email varchar(255), enabled boolean, failed_attempts integer, last_verified_at timestamp(6), locked boolean, locked_until timestamp(6), metadata TEXT, mfa_type varchar(255), country_code varchar(255), number varchar(255), is_primary boolean, qr_code_url TEXT, secret varchar(255), updated_at timestamp(6), updated_by varchar(255), user_id varchar(255), verified boolean, version bigint, primary key (id));
create table user_mfa_backup_codes (user_mfa_id varchar(255) not null, backup_code varchar(255), idx integer not null, primary key (user_mfa_id, idx));
create table user_preferences (id varchar(255) not null, accessibility TEXT, active boolean, application_id varchar(255), created_at timestamp(6), dashboard TEXT, notification TEXT, regional TEXT, tenant_id varchar(255), ui TEXT, updated_at timestamp(6), user_id varchar(255), version bigint, primary key (id));
create table user_sessions (id varchar(255) not null, access_token_id varchar(255), active boolean, browser varchar(255), city varchar(255), country varchar(255), created_at timestamp(6), credential_id varchar(255), device_id varchar(255), device_type varchar(255), expires_at timestamp(6), forced_logout boolean, ip_address varchar(255), last_activity_at timestamp(6), login_at timestamp(6), logout_at timestamp(6), logout_reason varchar(255), metadata TEXT, mfa_verified boolean, operating_system varchar(255), provider varchar(255), refresh_token_hash varchar(255), remember_me boolean, revoked boolean, session_id varchar(255), state varchar(255), updated_at timestamp(6), user_agent varchar(255), user_id varchar(255), version bigint, primary key (id));

alter table api_clients add constraint uk_client_id unique (client_id);
alter table applications add constraint uk_application_code unique (code);
alter table groups add constraint uk_tenant_group_code unique (tenant_id, code);
alter table permissions add constraint uk_permission_code unique (code);
alter table refresh_tokens add constraint uk_refresh_token_id unique (token_id);
alter table security_policies add constraint uk_tenant_application unique (tenant_id, application_id);
alter table tenants add constraint uk_tenant_code unique (code);
alter table uam_roles add constraint uk_uam_role_code unique (code);
alter table uam_users add constraint uk_uam_user_user_name unique (user_name);
alter table uam_users add constraint uk_uam_user_email unique (email);
alter table uam_users add constraint uk_uam_user_phone_number unique (number);
alter table user_credentials add constraint uk_provider_provider_user_id unique (provider, provider_user_id);
alter table user_devices add constraint uk_user_device unique (user_id, device_fingerprint);
alter table user_login_security add constraint uk_user_login_security_user_id unique (user_id);
alter table user_mfa add constraint uk_user_provider unique (user_id, mfa_type);
alter table user_preferences add constraint uk_user_application unique (user_id, application_id);
alter table user_sessions add constraint uk_user_session_session_id unique (session_id);
alter table user_sessions add constraint uk_user_session_refresh_token_hash unique (refresh_token_hash);

alter table api_client_allowed_ips add constraint fk_api_client_allowed_ips_client foreign key (api_client_id) references api_clients (id);
alter table api_client_grant_types add constraint fk_api_client_grant_types_client foreign key (api_client_id) references api_clients (id);
alter table api_client_redirect_uris add constraint fk_api_client_redirect_uris_client foreign key (api_client_id) references api_clients (id);
alter table api_client_role_ids add constraint fk_api_client_role_ids_client foreign key (api_client_id) references api_clients (id);
alter table api_client_scopes add constraint fk_api_client_scopes_client foreign key (api_client_id) references api_clients (id);
alter table group_roles add constraint fk_group_roles_group foreign key (group_id) references groups (id);
alter table group_users add constraint fk_group_users_group foreign key (group_id) references groups (id);
alter table notification_template_variables add constraint fk_notification_template_variables_template foreign key (template_id) references notification_templates (id);
alter table uam_role_permissions add constraint fk_uam_role_permissions_role foreign key (role_id) references uam_roles (id);
alter table uam_user_roles add constraint fk_uam_user_roles_user foreign key (user_id) references uam_users (id);
alter table user_mfa_backup_codes add constraint fk_user_mfa_backup_codes_mfa foreign key (user_mfa_id) references user_mfa (id);
